const resolveReminderAgentRoomAuthority = `-- name: ResolveReminderAgentRoomAuthority :one
SELECT room.tenant_id, caller.id AS actor_id, membership.role
FROM rooms room
JOIN actors caller
  ON caller.tenant_id=room.tenant_id
 AND caller.id=$1::text
 AND caller.kind='agent'
JOIN agent_registrations registration
  ON registration.actor_id=caller.id
 AND registration.tenant_id=caller.tenant_id
 AND registration.agent_management_id=$2::text
 AND registration.status='active'
JOIN room_members membership
  ON membership.room_id=room.id
 AND membership.actor_id=caller.id
WHERE room.id=$3::text
  AND room.deleted_at IS NULL
  AND room_actor_participating(room.id, caller.id)
FOR KEY SHARE OF membership, registration
`

type ResolveReminderAgentRoomAuthorityParams struct {
	ActorID           string `json:"actor_id"`
	AgentManagementID string `json:"agent_management_id"`
	RoomID            string `json:"room_id"`
}

type ResolveReminderAgentRoomAuthorityRow struct {
	TenantID string `json:"tenant_id"`
	ActorID  string `json:"actor_id"`
	Role     string `json:"role"`
}

func (q *Queries) ResolveReminderAgentRoomAuthority(ctx context.Context, arg ResolveReminderAgentRoomAuthorityParams) (ResolveReminderAgentRoomAuthorityRow, error) {
	row := q.db.QueryRow(ctx, resolveReminderAgentRoomAuthority, arg.ActorID, arg.AgentManagementID, arg.RoomID)
	var i ResolveReminderAgentRoomAuthorityRow
	err := row.Scan(&i.TenantID, &i.ActorID, &i.Role)
	return i, err
}

